    public static PgProcEntity[] GetPgProcEntities()
    {
        return [
            new PgProcEntity { Oid = 16667, Proname = "search_available_books", Pronamespace = 16387, Proowner = 10, Prolang = 14, Procost = 100.0f, Prorows = 1000.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = true, Provolatile = "s", Proparallel = "u", Pronargs = 1, Pronargdefaults = 0, Prorettype = 2249, Proargtypes = "1043", Proallargtypes = [1043, 23, 1043, 1043, 25, 1043, 1043], Proargmodes = "{i,t,t,t,t,t,t}", Proargnames = ["search_term", "book_id", "full_title", "title", "description", "authors", "genres"], Proargdefaults = null, Protrftypes = null, Prosrc = "\n    SELECT b.book_id, b.full_title, s.title, s.description, s.authors, s.genres\n    FROM library_activity.available_books AS b\n    JOIN library_catalog.book_search AS s ON s.book_id = b.book_id\n    WHERE to_tsvector('english', coalesce(s.title, '') || ' ' || coalesce(s.description, '') || ' '\n          || coalesce(s.authors, '') || ' ' || coalesce(s.genres, ''))\n          @@ plainto_tsquery('english', search_term)\n       OR b.full_title ILIKE '%' || search_term || '%'\n       OR s.description ILIKE '%' || search_term || '%'\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16668, Proname = "deactivate_stale_users", Pronamespace = 16386, Proowner = 10, Prolang = 14, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2278, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\n    UPDATE library_identity.site_user\n    SET is_active = FALSE\n    WHERE is_active = TRUE\n      AND last_login < CURRENT_TIMESTAMP - INTERVAL '1 year'\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16643, Proname = "set_genre_full_name", Pronamespace = 16385, Proowner = 10, Prolang = 13647, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2279, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\nDECLARE\n    parent_name varchar(25);\nBEGIN\n    IF NEW.parent_id IS NOT NULL THEN\n        SELECT g.short_name INTO parent_name\n        FROM library_catalog.genre AS g\n        WHERE g.genre_id = NEW.parent_id;\n        IF parent_name IS NULL THEN\n            RAISE EXCEPTION 'Parent genre does not exist.';\n        END IF;\n    END IF;\n\n    IF NEW.parent_id IS NULL AND EXISTS (\n        SELECT 1 FROM library_catalog.genre AS g\n        WHERE g.short_name = NEW.short_name AND g.genre_id <> coalesce(NEW.genre_id, -1)\n    ) THEN\n        RAISE EXCEPTION 'A genre with this short name already exists at the root level.';\n    END IF;\n\n    NEW.full_name := CASE\n        WHEN parent_name IS NULL THEN NEW.short_name\n        ELSE parent_name || ' / ' || NEW.short_name\n    END;\n    RETURN NEW;\nEND;\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16645, Proname = "sync_book_search", Pronamespace = 16385, Proowner = 10, Prolang = 13647, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2279, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        DELETE FROM library_catalog.book_search WHERE book_id = OLD.book_id;\n        RETURN OLD;\n    ELSIF TG_OP = 'INSERT' THEN\n        INSERT INTO library_catalog.book_search (book_id, title, description)\n        VALUES (NEW.book_id, NEW.full_title, NEW.description);\n        RETURN NEW;\n    ELSE\n        UPDATE library_catalog.book_search\n        SET title = NEW.full_title, description = NEW.description\n        WHERE book_id = NEW.book_id;\n        RETURN NEW;\n    END IF;\nEND;\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16649, Proname = "sync_book_authors", Pronamespace = 16385, Proowner = 10, Prolang = 13647, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2279, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\nDECLARE\n    target_book_id integer;\nBEGIN\n    target_book_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.book_id ELSE NEW.book_id END;\n    UPDATE library_catalog.book_search AS s\n    SET authors = (\n        SELECT string_agg(c.full_name, ', ' ORDER BY ba.display_order)\n        FROM library_catalog.book_author AS ba\n        JOIN library_catalog.contributor AS c ON c.contributor_id = ba.contributor_id\n        WHERE ba.book_id = target_book_id\n    )\n    WHERE s.book_id = target_book_id;\n    IF TG_OP = 'DELETE' THEN\n        RETURN OLD;\n    END IF;\n    RETURN NEW;\nEND;\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16653, Proname = "sync_book_genres", Pronamespace = 16385, Proowner = 10, Prolang = 13647, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2279, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\nDECLARE\n    target_book_id integer;\nBEGIN\n    target_book_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.book_id ELSE NEW.book_id END;\n    UPDATE library_catalog.book_search AS s\n    SET genres = (\n        SELECT string_agg(g.full_name, ', ' ORDER BY bg.display_order)\n        FROM library_catalog.book_genre AS bg\n        JOIN library_catalog.genre AS g ON g.genre_id = bg.genre_id\n        WHERE bg.book_id = target_book_id\n    )\n    WHERE s.book_id = target_book_id;\n    IF TG_OP = 'DELETE' THEN\n        RETURN OLD;\n    END IF;\n    RETURN NEW;\nEND;\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16657, Proname = "log_active_rental", Pronamespace = 16387, Proowner = 10, Prolang = 13647, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2279, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\nBEGIN\n    IF TG_OP = 'DELETE' THEN\n        INSERT INTO library_activity.rental_log\n            (rental_id, book_id, patron_id, rental_date, due_date, return_date,\n             fees_charged, fees_paid, notes, log_date)\n        VALUES\n            (OLD.rental_id, OLD.book_id, OLD.patron_id, OLD.rental_date, OLD.due_date,\n             OLD.return_date, OLD.fees_charged, OLD.fees_paid, OLD.notes, CURRENT_TIMESTAMP);\n        RETURN OLD;\n    END IF;\n\n    INSERT INTO library_activity.rental_log\n        (rental_id, book_id, patron_id, rental_date, due_date, return_date,\n         fees_charged, fees_paid, notes, log_date)\n    VALUES\n        (NEW.rental_id, NEW.book_id, NEW.patron_id, NEW.rental_date, NEW.due_date,\n         NEW.return_date, NEW.fees_charged, NEW.fees_paid, NEW.notes, CURRENT_TIMESTAMP);\n    RETURN NEW;\nEND;\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
            new PgProcEntity { Oid = 16658, Proname = "guard_active_rental_delete", Pronamespace = 16387, Proowner = 10, Prolang = 13647, Procost = 100.0f, Prorows = 0.0f, Provariadic = 0, Prosupport = "-", Prokind = "f", Prosecdef = false, Proleakproof = false, Proisstrict = false, Proretset = false, Provolatile = "v", Proparallel = "u", Pronargs = 0, Pronargdefaults = 0, Prorettype = 2279, Proargtypes = "", Proallargtypes = null, Proargmodes = null, Proargnames = null, Proargdefaults = null, Protrftypes = null, Prosrc = "\nBEGIN\n    IF OLD.fees_charged > OLD.fees_paid THEN\n        RAISE EXCEPTION 'Cannot delete active rental with outstanding fees.';\n    END IF;\n    RETURN OLD;\nEND;\n", Probin = null, Prosqlbody = null, Proconfig = null, Proacl = null, },
